# Generated by build.py from recipe.yml for recipe dict-look-up-a-word. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'words' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'words/surly'), "bad-tempered and unfriendly`n")
[IO.File]::WriteAllText((Join-Path $PWD 'words/surl'), "the server that answers curl`n")
$server0 = Start-Process surl -ArgumentList '--directory', 'words', 'dict://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe dict://127.0.0.1:8080/d:surly } finally { Stop-Process $server0 }
